def balances(events):
    seen, cancelled = set(), set()
    postings, totals = {}, {}
    # Track retractions that reference postings not yet seen
    pending_retractions = {}

    for event in events:
        if event['id'] in seen:
            continue
        seen.add(event['id'])
        if event['kind'] == 'post':
            account, amount = event['account'], event['amount']
            postings[event['id']] = (account, amount)
            totals.setdefault(account, 0)
            totals[account] += amount
        else:
            target = event['target']
            if target in cancelled:
                continue
            # If the target posting hasn't arrived yet, remember this retraction
            if target not in postings:
                cancelled.add(target)
                if target not in pending_retractions:
                    pending_retractions[target] = []
                pending_retractions[target].append(event['id'])
            else:
                # Target posting exists, cancel it
                cancelled.add(target)
                account, amount = postings[target]
                totals[account] -= amount
                # If there were pending retractions for this target, cancel them too
                if target in pending_retractions:
                    for retraction_id in pending_retractions[target]:
                        cancelled.add(retraction_id)
                    del pending_retractions[target]
    # Handle any remaining pending retractions (they are unmatched)
    return totals

